query:
// Create direct relationships bw Stations
MATCH (trip:Trip)-[:FROM]->(fromS:Station)
MATCH (trip)-[:TO]->(toS:Station)
WITH fromS, toS, count(trip) AS nbTrips
MERGE (fromS)-[r:LINKS]->(toS)
  ON CREATE SET r.nbTrips = nbTrips;

// Graph projection
CYPHER runtime=parallel
OPTIONAL MATCH (source)-[r:LINKS]->(target:Station)
WITH gds.graph.project('myGraph', source, target, {
  sourceNodeProperties: source {},
  targetNodeProperties: target {},
  relationshipProperties: r { .nbTrips }
}, {
  memory: '4GB', ttl: duration({minutes: 30})
}) AS g
RETURN g.graphName, g.nodeCount, g.relationshipCount

// unweighted pagerank
CALL gds.pageRank.write('myGraph', {
  maxIterations: 20,
  dampingFactor: 0.85,
  writeProperty: 'pagerank'
})
YIELD nodePropertiesWritten, ranIterations

// Weighted pagerank
CALL gds.pageRank.write('myGraph', {
  maxIterations: 20,
  dampingFactor: 0.85,
  writeProperty: 'weightedPagerank',
  relationshipWeightProperty: 'nbTrips'
})
YIELD nodePropertiesWritten, ranIterations

MATCH path=(s:Station {station_id: $stationId})
  ((:Station)-[r:LINKS WHERE r.nbTrips > 100]->(:Station)){1,3}
RETURN path

// Parameters for pagerank algo
:params {
  iterations: 20,
  d: 0.85
}

// Read history
MATCH (s:Station {station_id: $stationId})
UNWIND range(0, size(s.ranks)-1) AS iter
RETURN s.station_name AS station, iter AS iteration, s.ranks[iter] AS rank
ORDER BY station, iteration;
